#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]() -> double {
        return chrono::duration<double>(chrono::steady_clock::now()-startTime).count();
    };

    int N;
    cin >> N;
    vector<double> x(N), y(N);
    for(int i=0;i<N;i++) cin >> x[i] >> y[i];

    vector<bool> is_prime(N+1, false);
    {
        vector<bool> sieve(N+1, true);
        if(N>=0) sieve[0]=false;
        if(N>=1) sieve[1]=false;
        for(int i=2;(long long)i*i<=N;i++)
            if(sieve[i])
                for(int j=i*i;j<=N;j+=i) sieve[j]=false;
        for(int i=0;i<=N;i++) is_prime[i]=sieve[i];
    }

    auto dist = [&](int a, int b) -> double {
        double dx=x[a]-x[b], dy=y[a]-y[b];
        return sqrt(dx*dx+dy*dy);
    };

    // Nearest neighbor heuristic
    vector<bool> visited(N, false);
    vector<int> tour;
    tour.reserve(N+1);
    tour.push_back(0);
    visited[0]=true;
    for(int step=1;step<N;step++){
        int last=tour.back();
        int best=-1; double bestD=1e18;
        for(int j=0;j<N;j++){
            if(!visited[j]){
                double d=dist(last,j);
                if(d<bestD){bestD=d;best=j;}
            }
        }
        tour.push_back(best);
        visited[best]=true;
    }
    tour.push_back(0);

    // step s (1-indexed): from tour[s-1] to tour[s]
    // penalty multiplier at step s
    auto mult = [&](int s, int src) -> double {
        return (s%10==0 && !is_prime[src]) ? 1.1 : 1.0;
    };

    auto tourCost = [&](const vector<int>& t) -> double {
        double cost=0;
        for(int s=1;s<=N;s++){
            double d=dist(t[s-1],t[s]);
            cost += d * mult(s, t[s-1]);
        }
        return cost;
    };

    double bestCost = tourCost(tour);

    // 2-opt with full recomputation for correctness (penalties depend on position)
    // For speed, limit window size
    int windowSize = (N<=2000) ? N : min(N, 100);

    for(int iter=0; iter<1000 && elapsed()<2.5; iter++){
        bool improved=false;
        for(int i=1; i<N && elapsed()<2.5; i++){
            int jmax=min(i+windowSize, N-1);
            for(int j=i+1; j<=jmax; j++){
                // Compute cost change for reversing tour[i..j]
                // Old edges: (i-1,i), (j,j+1) and internal edges + penalties
                // This is complex due to penalties; compute segment costs
                double oldSeg=0, newSeg=0;
                for(int s=i;s<=min(j+1,N);s++){
                    oldSeg += dist(tour[s-1],tour[s]) * mult(s, tour[s-1]);
                }
                reverse(tour.begin()+i, tour.begin()+j+1);
                for(int s=i;s<=min(j+1,N);s++){
                    newSeg += dist(tour[s-1],tour[s]) * mult(s, tour[s-1]);
                }
                if(newSeg < oldSeg - 1e-10){
                    bestCost += newSeg - oldSeg;
                    improved=true;
                } else {
                    reverse(tour.begin()+i, tour.begin()+j+1);
                }
            }
        }
        if(!improved) break;
        if(N>2000 && windowSize<N) windowSize=min(windowSize+20, N);
    }

    cout << N+1 << "\n";
    for(int i=0;i<=N;i++) cout << tour[i] << "\n";
}
